import numpy as np
from scipy import stats


def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    st = np.asarray(feats.stratum); lv = sorted(set(st.tolist()))
    S = np.column_stack([(st == s).astype(float) for s in lv[1:]]) if len(lv) > 1 else np.zeros((n, 1))
    rng = np.random.default_rng(0)

    def mat(cols):
        return np.column_stack([np.ones(n)] +
            [X[:, j] if not isinstance(j, tuple) else X[:, j[0]] * X[:, j[1]] for j in cols] + [S])

    def fit(cols):
        M = mat(cols); b = np.zeros(M.shape[1])
        for _ in range(30):
            mu = np.clip(1 / (1 + np.exp(-M @ b)), 1e-9, 1 - 1e-9); W = np.clip(mu * (1 - mu), 1e-6, None)
            try:
                s = np.linalg.solve((M.T * W) @ M + np.eye(M.shape[1]) * 1e-7, M.T @ (y - mu))
            except Exception:
                return -np.inf, mu, W, M
            b = b + s
            if np.abs(s).max() < 1e-8:
                break
        mu = np.clip(1 / (1 + np.exp(-M @ b)), 1e-9, 1 - 1e-9)
        return float(y @ np.log(mu) + (1 - y) @ np.log(1 - mu)), mu, np.clip(mu * (1 - mu), 1e-6, None), M

    def score(mu, W, M, P):
        V = P.T @ (W[:, None] * M)
        info = (P * P).T @ W - np.einsum('mk,kl,ml->m', V, np.linalg.pinv((M.T * W) @ M), V)
        return (P.T @ (y - mu)) ** 2 / np.clip(info, 1e-9, None)

    _, mu0, W0, M0 = fit([]); Z = np.column_stack([X, X * X]); V0 = Z.T @ (W0[:, None] * M0)
    info0 = np.clip((Z * Z).T @ W0 - np.einsum('mk,kl,ml->m', V0, np.linalg.pinv((M0.T * W0) @ M0), V0), 1e-9, None)
    mstat = lambda yy: np.cumsum(np.sort((Z.T @ (yy - mu0)) ** 2 / info0)[::-1][:4])
    obs = mstat(y); cnt = np.zeros(4)
    for _ in range(300):
        cnt += mstat(y[rng.permutation(n)]) >= obs
    gate_ok = (cnt / 300).min() <= 0.18 or p <= 30; del Z

    C = np.atleast_2d(np.corrcoef(X.T)); np.fill_diagonal(C, 0); aC = np.abs(C)
    sel = []; ll, mu, W, M = fit([])
    while gate_ok and len(sel) < MAX_DRIVERS:
        sc = score(mu, W, M, np.column_stack([X[:, j] for j in range(p)]))
        best, bp = None, (0.02 if not sel else 0.005)
        for j in np.argsort(-sc)[:8]:
            if j in sel or any(aC[j, s] >= 0.6 for s in sel):
                continue
            pj = stats.chi2.sf(max(0.0, 2 * (fit(sel + [j])[0] - ll)), 1)
            if pj < bp:
                best, bp = int(j), pj
        if best is None: break
        cl = [best] + [k for k in range(p) if aC[best, k] >= 0.6 and k not in sel]
        if len(cl) > 1:
            lls = {k: fit(sel + [k])[0] for k in cl}; top = max(lls.values())
            best = max([k for k in cl if lls[k] >= top - 2], key=lambda k: float((C[k, cl] ** 2).sum()))
        sel.append(best); ll, mu, W, M = fit(sel)
    for j in list(sel):
        if stats.chi2.sf(max(0.0, 2 * (ll - fit([s for s in sel if s != j])[0])), 1) > 0.01:
            sel.remove(j); ll = fit(sel)[0]
    ll, mu, W, M = fit(sel)
    pairs = [(a, b) for a in range(p) for b in range(a, p)]; stat = np.empty(len(pairs))
    for s0 in range(0, len(pairs), 2048):
        blk = pairs[s0:s0 + 2048]
        stat[s0:s0 + 2048] = score(mu, W, M, np.column_stack([X[:, a] * X[:, b] for a, b in blk]))
    prods = []; used = set()
    for ix in np.argsort(-stat)[:15]:
        a, b = pairs[ix]
        if a in used or b in used: continue
        base = sorted(set(sel) | {a} | {b})
        if stats.chi2.sf(max(0.0, 2 * (fit(base + [(a, b)])[0] - fit(base)[0])), 1) < 2e-6:
            prods.append((a, b)); used |= {a, b}; sel = base
        if len(prods) >= 2:
            break
    drv = list(dict.fromkeys(sel + [q for pr in prods for q in pr]))[:MAX_DRIVERS]
    return Design(drivers=tuple(ids[j] for j in drv), columns=tuple(ids[j] for j in sorted(sel)),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

